<?php
/** Phase 9 — additive editorial governance controls; native WP capabilities remain authoritative. */
if (!defined('ABSPATH')) exit;
if (!class_exists('BSW_Phase9_Governance')) {
final class BSW_Phase9_Governance {
 const AUDIT='bsw_p9_governance_audit';
 public static function init(){add_action('add_meta_boxes_wiki_article',array(__CLASS__,'box'));add_action('save_post_wiki_article',array(__CLASS__,'save'),40,2);add_action('transition_post_status',array(__CLASS__,'status_audit'),20,3);add_action('admin_menu',array(__CLASS__,'menu'),70);add_filter('manage_wiki_article_posts_columns',array(__CLASS__,'columns'));add_action('manage_wiki_article_posts_custom_column',array(__CLASS__,'column'),10,2);}
 public static function box(){add_meta_box('bsw_p9_governance','BIGSHOR Editorial Governance',array(__CLASS__,'render'),'wiki_article','normal','default');}
 public static function render($post){$review=get_post_meta($post->ID,'_bsw_p9_review_state',true)?:'not_reviewed';$notes=get_post_meta($post->ID,'_bsw_p9_review_notes',true);$reviewer=(int)get_post_meta($post->ID,'_bsw_p9_reviewer',true);wp_nonce_field('bsw_p9_save_'.$post->ID,'bsw_p9_nonce');echo '<p><label for="bsw_p9_state"><strong>Editorial review state</strong></label><br><select name="bsw_p9_state" id="bsw_p9_state">';foreach(array('not_reviewed'=>'Not reviewed','in_review'=>'In review','changes_requested'=>'Changes requested','reviewed'=>'Reviewed') as $k=>$v)echo '<option value="'.esc_attr($k).'" '.selected($review,$k,false).'>'.esc_html($v).'</option>';echo '</select></p><p><label for="bsw_p9_notes"><strong>Review notes</strong></label><textarea class="widefat" rows="4" name="bsw_p9_notes" id="bsw_p9_notes">'.esc_textarea($notes).'</textarea></p>';if($reviewer)echo '<p class="description">Last reviewer: '.esc_html(get_the_author_meta('display_name',$reviewer)).'</p>';echo '<p class="description">This record supplements, and does not replace, existing BIGSHOR Phase 36 checks or WordPress publishing capabilities.</p>';}
 public static function save($id,$post){if(wp_is_post_revision($id)||wp_is_post_autosave($id)||!isset($_POST['bsw_p9_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsw_p9_nonce'])),'bsw_p9_save_'.$id)||!current_user_can('edit_post',$id))return;$allowed=array('not_reviewed','in_review','changes_requested','reviewed');$state=sanitize_key(wp_unslash($_POST['bsw_p9_state']??'not_reviewed'));if(!in_array($state,$allowed,true))return;$old=get_post_meta($id,'_bsw_p9_review_state',true);$notes=sanitize_textarea_field(wp_unslash($_POST['bsw_p9_notes']??''));update_post_meta($id,'_bsw_p9_review_state',$state);update_post_meta($id,'_bsw_p9_review_notes',$notes);if($old!==$state){update_post_meta($id,'_bsw_p9_reviewer',get_current_user_id());update_post_meta($id,'_bsw_p9_reviewed_at',current_time('mysql'));self::audit('review_state_changed',$id,'Review state: '.($old?:'not set').' → '.$state);}}
 public static function status_audit($new,$old,$post){if(!$post||$post->post_type!=='wiki_article'||$new===$old||wp_is_post_revision($post->ID)||wp_is_post_autosave($post->ID))return;self::audit('status_transition',$post->ID,'Status changed from '.$old.' to '.$new);}
 private static function audit($event,$id,$detail){$rows=get_option(self::AUDIT,array());if(!is_array($rows))$rows=array();array_unshift($rows,array('time'=>current_time('mysql'),'user'=>get_current_user_id(),'event'=>sanitize_key($event),'post_id'=>absint($id),'detail'=>sanitize_text_field($detail)));update_option(self::AUDIT,array_slice($rows,0,750),false);}
 public static function columns($c){$c['bsw_p9_review']='Editorial review';return $c;}
 public static function column($col,$id){if($col==='bsw_p9_review')echo esc_html(ucwords(str_replace('_',' ',get_post_meta($id,'_bsw_p9_review_state',true)?:'not reviewed')));}
 public static function menu(){add_submenu_page('edit.php?post_type=wiki_article','Governance activity','Governance activity','manage_options','bsw-p9-audit',array(__CLASS__,'page'));}
 public static function page(){if(!current_user_can('manage_options'))wp_die('Permission denied.',403);$rows=get_option(self::AUDIT,array());echo '<div class="wrap"><h1>BIGSHOR Governance Activity</h1><p>Recent editorial review and publication status events. This log is bounded to the latest 750 events.</p><table class="widefat striped"><thead><tr><th>Date</th><th>Event</th><th>Article</th><th>User</th><th>Details</th></tr></thead><tbody>';foreach((array)$rows as $r){$u=get_userdata(absint($r['user']??0));$p=get_post(absint($r['post_id']??0));echo '<tr><td>'.esc_html($r['time']??'').'</td><td>'.esc_html($r['event']??'').'</td><td>'.($p?'<a href="'.esc_url(get_edit_post_link($p->ID)).'">'.esc_html(get_the_title($p)).'</a>':'—').'</td><td>'.esc_html($u?$u->display_name:'System').'</td><td>'.esc_html($r['detail']??'').'</td></tr>'; }echo '</tbody></table></div>';}
}
BSW_Phase9_Governance::init();
}
